const {chromium}=require('playwright');const U='http://localhost:8765/';
(async()=>{const b=await chromium.launch();const p=await b.newPage({viewport:{width:1280,height:900}});const errs=[];p.on('pageerror',e=>errs.push(e.message));
const ok=(n,c)=>console.log((c?'PASS ':'FAIL ')+n);
await p.goto(U+'#/patient');await p.evaluate(()=>{localStorage.clear();localStorage.setItem('kafila-entry','1');localStorage.setItem('screenpath-tour','{"open":false}');localStorage.setItem('screenpath-demo-ui','0')});await p.reload();await p.waitForTimeout(700);
ok('no screen dropdown',await p.locator('#screenChip').count()===0);
const order=await p.evaluate(()=>[...document.querySelectorAll('.demo-btn')].map(b=>b.textContent.trim()).join('|'));ok('top bar order '+order,/Choose a person\|▶ 3-minute tour\|⚙ Demo tools/.test(order));
await p.click('#startBtn');ok('chooser opens',await p.isVisible('#entry'));
await p.click('#entry [data-e="2"]');await p.waitForTimeout(400);let t=await p.locator('#view').innerText();ok('coordinator line',/You are looking at Noura's screen \(care coordinator\)/.test(t)||/You now see Noura's screen/.test(t));
await p.click('#startBtn');await p.click('#entry [data-e="3"]');await p.waitForTimeout(400);ok('gp -> case',p.url().endsWith('#/case/C-1043'));
await p.evaluate(()=>{Store.S.data.ui.banner=null;Store.save()});await p.waitForTimeout(200);t=await p.locator('#view').innerText();ok('gp line',/You are looking at Dr. Hessa's screen \(family doctor\)/.test(t));
await p.click('#startBtn');await p.click('#entry [data-e="5"]');await p.waitForTimeout(400);ok('lead -> dashboard',p.url().endsWith('#/dashboard'));
await p.click('#demoBtn');await p.waitForTimeout(200);
await p.evaluate(([i,v])=>{const s=document.querySelector('#'+i);s.value=v;s.dispatchEvent(new Event('change'))},['role','clinlead']);await p.waitForTimeout(400);ok('select clinlead -> team',p.url().endsWith('#/team'));
await p.setViewportSize({width:390,height:800});await p.goto(U+'#/patient');await p.waitForTimeout(400);
const ov=await p.evaluate(()=>document.documentElement.scrollWidth>innerWidth);ok('no horizontal scroll mobile',!ov);
console.log('errors',errs);await b.close()})();
